const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;
const L = data[idx++], C = data[idx++], P = data[idx++];

const black = Array.from({ length: L }, () => new Uint8Array(C));
for (let i = 0; i < P; i++) {
  black[data[idx++] - 1][data[idx++] - 1] = 1;
}

// Para cada linha: máscara de células que podem ser brancas (livres e vizinhas de alguma peça preta)
// e máscara de peças pretas.
const rowCand = new Array(L);
const rowBlack = new Array(L);
for (let r = 0; r < L; r++) {
  let cm = 0, bm = 0;
  for (let c = 0; c < C; c++) {
    if (black[r][c]) { bm |= 1 << c; continue; }
    const hasBlackNeighbor =
      (r > 0 && black[r - 1][c]) ||
      (r < L - 1 && black[r + 1][c]) ||
      (c > 0 && black[r][c - 1]) ||
      (c < C - 1 && black[r][c + 1]);
    if (hasBlackNeighbor) cm |= 1 << c;
  }
  rowCand[r] = cm;
  rowBlack[r] = bm;
}

const pc = m => { let n = 0; while (m) { m &= m - 1; n++; } return n; };

// Gera todas as máscaras válidas (subconjuntos sem peças brancas adjacentes horizontalmente)
function getValid(mask) {
  const arr = [];
  for (let m = mask; ; m = (m - 1) & mask) {
    if ((m & (m << 1)) === 0) arr.push(m);
    if (m === 0) break;
  }
  return arr;
}

// DP por linhas: dp[mask] = máx. de brancas até a linha atual, com 'mask' sendo as brancas da linha atual
const FULL = 1 << C;
let dp = new Array(FULL).fill(-1);
dp[0] = 0;

for (let r = 0; r < L; r++) {
  const masks = getValid(rowCand[r]);
  const ndp = new Array(FULL).fill(-1);
  for (const m of masks) {
    const add = pc(m);
    for (let pm = 0; pm < FULL; pm++) {
      if (dp[pm] < 0) continue;
      if (m & pm) continue; // conflito vertical entre brancas
      const val = dp[pm] + add;
      if (val > ndp[m]) ndp[m] = val;
    }
  }
  dp = ndp;
}

let ans = 0;
for (const v of dp) if (v > ans) ans = v;
console.log(ans);
